import{_ as t,o as e,c as r,a3 as l}from"./chunks/framework.Bh_aNVBG.js";const i="/images/partner/image%204.png",u=JSON.parse('{"title":"4. 스탬프 투어 보상 수령","description":"","frontmatter":{},"headers":[],"relativePath":"partner/chapter-4.md","filePath":"partner/chapter-4.md"}'),o={name:"partner/chapter-4.md"};function d(h,a,n,p,s,_){return e(),r("div",null,[...a[0]||(a[0]=[l('<h1 id="_4-스탬프-투어-보상-수령" tabindex="-1">4. 스탬프 투어 보상 수령 <a class="header-anchor" href="#_4-스탬프-투어-보상-수령" aria-label="Permalink to &quot;4. 스탬프 투어 보상 수령&quot;">​</a></h1><p>스탬프 투어 보상 수령 기능은 스탬프 코스를 완주한 방문객의 보상 수령 자격을 확인하고 보상을 지급하기 위한 기능입니다.</p><p>파트너는 방문객의 보상 수령 QR 코드를 스캔하여 보상 수령 가능 여부를 확인할 수 있습니다.</p><h2 id="_4-1-스탬프-투어-보상-수령-기능-안내" tabindex="-1">4.1. 스탬프 투어 보상 수령 기능 안내 <a class="header-anchor" href="#_4-1-스탬프-투어-보상-수령-기능-안내" aria-label="Permalink to &quot;4.1. 스탬프 투어 보상 수령 기능 안내&quot;">​</a></h2><p>스탬프 투어 보상은 행사 운영 담당자가 설정한 보상 정책 및 지급 조건에 따라 제공됩니다.</p><p>파트너는 행사 현장에서 방문객의 보상 수령 QR 코드를 확인하고 보상 지급 업무를 수행합니다.</p><table tabindex="0"><thead><tr><th>구분</th><th>역할</th></tr></thead><tbody><tr><td>행사 운영 담당자</td><td>스탬프 투어 및 보상 정책 설정</td></tr><tr><td>파트너</td><td>보상 수령 QR 코드 스캔 및 현장 보상 지급</td></tr><tr><td>방문객</td><td>스탬프 투어 참여 및 보상 수령</td></tr></tbody></table><h2 id="_4-2-보상-수령-화면" tabindex="-1">4.2. 보상 수령 화면 <a class="header-anchor" href="#_4-2-보상-수령-화면" aria-label="Permalink to &quot;4.2. 보상 수령 화면&quot;">​</a></h2><ol><li>프로젝트별 CMS 접속 주소에 접속합니다.</li><li>발급받은 파트너 계정으로 로그인합니다.</li><li><strong>스탬프 투어 보상 수령</strong> 메뉴를 선택합니다.</li><li>보상 수령 화면을 확인합니다.</li></ol><p><img src="'+i+'" alt="image.png"></p><h2 id="_4-3-보상-수령-qr-코드-스캔" tabindex="-1">4.3. 보상 수령 QR 코드 스캔 <a class="header-anchor" href="#_4-3-보상-수령-qr-코드-스캔" aria-label="Permalink to &quot;4.3. 보상 수령 QR 코드 스캔&quot;">​</a></h2><p>방문객이 스탬프 투어를 완주하고 보상 수령을 요청하면 보상 수령 QR 코드를 확인합니다.</p><h3 id="_1-보상-수령-qr-코드-확인" tabindex="-1">① 보상 수령 QR 코드 확인 <a class="header-anchor" href="#_1-보상-수령-qr-코드-확인" aria-label="Permalink to &quot;① 보상 수령 QR 코드 확인&quot;">​</a></h3><p>방문객에게 방문객용 안내 페이지의 스탬프 코스 인증 카드 내 보상 수령 QR 코드를 제시하도록 안내합니다.</p><h3 id="_2-qr-코드-스캔" tabindex="-1">② QR 코드 스캔 <a class="header-anchor" href="#_2-qr-코드-스캔" aria-label="Permalink to &quot;② QR 코드 스캔&quot;">​</a></h3><ol><li>보상 수령 화면으로 이동합니다.</li><li>방문객이 제시한 보상 수령 QR 코드를 스캔합니다.</li><li>화면에 표시되는 처리 결과를 확인합니다.</li></ol><h3 id="_3-보상-지급" tabindex="-1">③ 보상 지급 <a class="header-anchor" href="#_3-보상-지급" aria-label="Permalink to &quot;③ 보상 지급&quot;">​</a></h3><p>QR 코드 스캔 결과를 확인한 후 보상 수령이 가능한 방문객에게 보상을 지급합니다.</p><p>보상 수령이 불가능하거나 오류가 발생한 경우 화면에 표시되는 안내 내용을 확인합니다.</p><h2 id="_4-4-보상-지급-시-유의사항" tabindex="-1">4.4. 보상 지급 시 유의사항 <a class="header-anchor" href="#_4-4-보상-지급-시-유의사항" aria-label="Permalink to &quot;4.4. 보상 지급 시 유의사항&quot;">​</a></h2><p>보상 지급 업무를 수행할 때는 다음 사항에 유의해 주세요.</p><ul><li>QR 코드 스캔 결과를 확인한 후 보상을 지급합니다.</li><li>이미 보상을 수령한 방문객에게 중복 지급하지 않도록 주의합니다.</li><li>보상 수령이 불가능한 경우 화면에 표시되는 안내 내용을 확인합니다.</li><li>실제 보상 재고가 부족한 경우 행사 운영 담당자에게 문의합니다.</li><li>QR 코드 스캔 또는 보상 수령 처리 중 오류가 발생한 경우 처리 결과를 확인한 후 후속 조치를 진행합니다.</li></ul><blockquote><p><strong>참고</strong></p><p>스탬프 투어 코스, 완주 기준 및 보상 정책은 행사 운영 담당자가 설정합니다.</p><p>보상 지급 조건의 변경이 필요한 경우 행사 운영 담당자에게 문의해 주세요.</p></blockquote>',23)])])}const q=t(o,[["render",d]]);export{u as __pageData,q as default};
